// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testRegression_property() public {
        vm.deal(address(c), 2 ether);
        vm.prank(c.Owner());
        c.Command{value: 1 ether}(address(0), "");
        vm.deal(c.Owner(), 1 ether);
        vm.prank(c.Owner());
        c.Command{value: 1 wei}(address(0), "");
        vm.deal(address(c), 1 wei);
        vm.prank(c.Owner());
        c.Command{value: 1 wei}(address(0), "");
        bool refReverted = false;
        vm.prank(c.Owner());
        try c.withdraw() { } catch { refReverted = true; }
        assertTrue(refReverted, "Reference should revert on withdraw to contract Owner");
    }
}
